mapper.select:
SELECT COUNT(*)
FROM USERS
WHERE userId = #{userId}

SELECT * FROM ( SELECT u.user_no AS userNo, u.role, u.userId, u.userPwd, u.addr, u.name, u.phone, u.phone_verified AS phoneVerified, u.email, u.email_verified AS emailVerified, u.email_verify_token AS emailVerifyToken, u.email_verify_expired_at AS emailVerifyExpiredAt, u.birth, u.gender, u.photo, u.last_login_at AS lastLoginAt, u.created_date AS createdDate, u.updated_date AS updatedDate, u.is_blocked AS isBlocked, u.block_reason AS blockReason, u.blocked_at AS blockedAt, ROW_NUMBER() OVER (ORDER BY u.created_date DESC) AS rn FROM USERS u
( u.userId LIKE '%' || #{keyword} || '%' OR u.name LIKE '%' || #{keyword} || '%' OR u.email LIKE '%' || #{keyword} || '%' )
AND u.role = #{role}
AND u.is_blocked = #{blocked}
) WHERE rn BETWEEN #{offset} + 1 AND #{offset} + #{size}

